<?php
namespace GlpiPlugin\Projectflow\Application;
use GlpiPlugin\Projectflow\Service\ReferenceService;use GlpiPlugin\Projectflow\Service\TaskService;use Session;
class MyTasksController{public function index():array{$tasks=(new TaskService())->getMyTasks();$now=time();$today=strtotime('today 23:59:59',$now);$week=strtotime('+7 days',$now);$stats=['total'=>count($tasks),'overdue'=>0,'today'=>0,'next7'=>0,'without_date'=>0,'attention'=>0,'reminders'=>0];foreach($tasks as $t){$stats['attention']+=(int)!empty($t['attention']);$stats['reminders']+=(int)!empty($t['reminder_due']);if($t['is_overdue']){$stats['overdue']++;continue;}if(!$t['plan_end_ts']){$stats['without_date']++;continue;}if($t['plan_end_ts']<=$today)$stats['today']++;elseif($t['plan_end_ts']<=$week)$stats['next7']++;}$refs=new ReferenceService();return['tasks'=>$tasks,'stats'=>$stats,'dashboard_url'=>PLUGIN_PROJECTFLOW_WEBDIR.'/front/index.php','ajax_task_url'=>PLUGIN_PROJECTFLOW_WEBDIR.'/ajax/task.php','csrf_token'=>Session::getNewCSRFToken(),'states'=>$refs->getProjectStates(),'priorities'=>$refs->getPriorities()];}}
